"""
Writes e2e/flows/20-offline-modules.yaml: with the phone offline, taps every module of the More screen and checks that
none shows the "can't reach the server" error. Uses test IDs (module-<id>, error-network), so it works in any language
and does not need the app to reload its code (it never opens a link while offline).

Run from the repo root:  python e2e/make_offline_flow.py
"""
import re

ids = re.findall(r"\{ id: '([^']+)', route: '[^']*'", open('src/lib/modules.ts', encoding='utf-8').read())

lines = [
    '# Generated by e2e/make_offline_flow.py: do not edit by hand.',
    '# The phone must have been online for a few minutes before, with "All modules saved" in the sync sheet (flow 10).',
    '# Needs: APP_ID, LINK_BASE (see e2e/README.md).',
    'appId: ${APP_ID}',
    '---',
    '- launchApp:',
    '    stopApp: false',
    '- openLink: "${LINK_BASE}more"',
    '- runFlow:',
    '    when:',
    '      visible:',
    '        id: "sync-close"',
    '    commands:',
    '      - tapOn:',
    '          id: "sync-close"',
    '# opening the app starts the background sync again: wait until it has finished (the pill is green) before going offline',
    '- extendedWaitUntil:',
    '    visible:',
    '      id: "sync-pill-ok"',
    '    timeout: 300000',
    '- setAirplaneMode: enabled',
    '- extendedWaitUntil:',
    '    visible:',
    '      id: "sync-pill-offline"',
    '    timeout: 60000',
]
for m in ids:
    tile = f'module-{m}'
    lines += [
        f'# --- {m}',
        '- runFlow:',
        '    when:',
        '      notVisible:',
        f'        id: "{tile}"',
        '    commands:',
        '      - scrollUntilVisible:',
        '          element:',
        f'            id: "{tile}"',
        '          direction: UP',
        '          timeout: 8000',
        '          optional: true',
        '- runFlow:',
        '    when:',
        '      notVisible:',
        f'        id: "{tile}"',
        '    commands:',
        '      - scrollUntilVisible:',
        '          element:',
        f'            id: "{tile}"',
        '          direction: DOWN',
        '          timeout: 8000',
        '          optional: true',
        '- runFlow:',
        '    when:',
        '      visible:',
        f'        id: "{tile}"',
        '    commands:',
        '      - tapOn:',
        f'          id: "{tile}"',
        '      - waitForAnimationToEnd:',
        '          timeout: 5000',
        '      - takeScreenshot: "offline-' + m + '"',
        '      - assertNotVisible:',
        '          id: "error-network"',
        '      - back',
        '      - waitForAnimationToEnd:',
        '          timeout: 2000',
    ]
lines += ['- setAirplaneMode: disabled', '']
open('e2e/flows/20-offline-modules.yaml', 'w', encoding='utf-8', newline='\n').write('\n'.join(lines))
print(len(ids), 'modules')
